def download_markdown(url, subdirectory=None, **_extra):
    import json, os, datetime, time, hashlib, re, urllib.parse, urllib.request

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0037000" if __import__("os").path.isdir("./environment_mix/0037000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- basic request log / quota enforcement (best-effort; schema did not define logs) ---
    # Since no usage/audit collection is declared, we do not enforce rate limits here.

    # --- validate inputs ---
    if not isinstance(url, str) or not url.strip():
        return _err("VALIDATION_ERROR", "url must be a non-empty string")
    url_in = url.strip()

    if subdirectory is not None and not isinstance(subdirectory, str):
        return _err("VALIDATION_ERROR", "subdirectory must be a string when provided")
    subdir_in = subdirectory.strip() if isinstance(subdirectory, str) else None
    if subdir_in == "":
        subdir_in = None

    def _is_valid_http_url(u):
        try:
            p = urllib.parse.urlparse(u)
        except Exception:
            return False
        if p.scheme not in ("http", "https"):
            return False
        if not p.netloc:
            return False
        return True

    if not _is_valid_http_url(url_in):
        # Create job as failed? Business rules: download_markdown creates job then transitions;
        # but for invalid URL, we treat as validation error (tool description).
        return _err("VALIDATION_ERROR", "url must be a valid http(s) URL")

    def _normalize_url(u):
        p = urllib.parse.urlparse(u)
        scheme = p.scheme.lower()
        netloc = p.netloc.strip()
        # Remove default ports
        host, sep, port = netloc.partition(":")
        if sep:
            if (scheme == "http" and port == "80") or (scheme == "https" and port == "443"):
                netloc = host
        # normalize path: keep as-is but remove redundant trailing slash except root
        path = p.path or "/"
        if path != "/" and path.endswith("/"):
            path = path.rstrip("/")
        # sort query params for stable canonicalization
        q = urllib.parse.parse_qsl(p.query, keep_blank_values=True)
        q.sort()
        query = urllib.parse.urlencode(q, doseq=True)
        frag = ""  # drop fragment
        return urllib.parse.urlunparse((scheme, netloc, path, p.params, query, frag))

    source_url_norm = _normalize_url(url_in)
    fetch_url = "https://r.jina.ai/" + source_url_norm
    if not fetch_url.startswith("https://r.jina.ai/"):
        return _err("VALIDATION_ERROR", "fetch_url must start with 'https://r.jina.ai/'")

    # --- load settings; create default active if missing (business rule) ---
    settings = _load("download_settings.json")
    subdirs = _load("subdirectories.json")
    jobs = _load("download_jobs.json")
    files = _load("markdown_files.json")

    def _norm_abs_path(pth):
        # canonical normalized absolute path without trailing separator (except root)
        pth2 = os.path.normpath(pth)
        # normpath may remove trailing slash; ensure absolute check uses original semantics
        pth2 = os.path.abspath(pth2)
        if len(pth2) > 1 and pth2.endswith(os.sep):
            pth2 = pth2.rstrip(os.sep)
        return pth2

    def _new_id(prefix):
        # simple unique id: prefix_YYYYMMDDHHMMSS_random
        import secrets
        ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S")
        return f"{prefix}_{ts}_{secrets.token_hex(8)}"

    def _get_active_settings():
        act = [r for r in settings if isinstance(r, dict) and r.get("active") is True and r.get("status") == "active"]
        # Enforce unique(active)=true; if multiple, pick most recently updated
        if not act:
            return None
        act.sort(key=lambda r: (r.get("updated_at") or "", r.get("created_at") or ""), reverse=True)
        return act[0]

    active = _get_active_settings()
    if active is None:
        # create a platform-default root_directory
        default_root = os.path.join(os.path.expanduser("~") or os.getcwd(), "markdown_downloads")
        default_root_norm = _norm_abs_path(default_root)
        # ensure absolute
        if not os.path.isabs(default_root_norm):
            default_root_norm = _norm_abs_path(os.getcwd())
        # create directory
        try:
            os.makedirs(default_root_norm, exist_ok=True)
        except OSError:
            # can't create: treat as failed precondition
            return _err("CONFLICT", "Unable to create default download directory on this system")
        rec = {
            "id": _new_id("dset"),
            "active": True,
            "root_directory": default_root_norm,
            "root_directory_normalized": default_root_norm,
            "allow_relative_subdirectories": False,
            "max_path_length": 4096,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        settings.append(rec)
        _save("download_settings.json", settings)
        active = rec

    # validate settings constraints quickly
    root_norm = active.get("root_directory_normalized")
    if not isinstance(root_norm, str) or not root_norm or not os.path.isabs(root_norm):
        return _err("CONFLICT", "Active download settings have an invalid root_directory")
    max_path_length = active.get("max_path_length")
    if not isinstance(max_path_length, int) or max_path_length < 64 or max_path_length > 32767:
        return _err("CONFLICT", "Active download settings have an invalid max_path_length")

    # ensure root directory exists
    try:
        os.makedirs(root_norm, exist_ok=True)
    except OSError as e:
        return _err("CONFLICT", "Configured download directory cannot be created/used", detail=str(e))

    # --- resolve subdirectory (must exist, no auto-create per rule) ---
    subdir_row = None
    if subdir_in is not None:
        # validate name rules
        if len(subdir_in) < 1 or len(subdir_in) > 128:
            return _err("VALIDATION_ERROR", "subdirectory length must be between 1 and 128")
        if subdir_in in (".", ".."):
            return _err("VALIDATION_ERROR", "subdirectory must not be '.' or '..'")
        if "\x00" in subdir_in:
            return _err("VALIDATION_ERROR", "subdirectory must not contain NUL byte")
        if active.get("allow_relative_subdirectories") is False:
            if ("/" in subdir_in) or ("\\" in subdir_in):
                return _err("VALIDATION_ERROR", "subdirectory must be a single segment (no path separators)")

        name_norm = subdir_in.strip().lower()
        candidates = [
            r for r in subdirs
            if isinstance(r, dict)
            and r.get("settings_id") == active["id"]
            and r.get("status") == "active"
            and r.get("name_normalized") == name_norm
        ]
        if not candidates:
            # Per business rule, fail with job error_code='path_error' (not tool error)
            # We will create a job record and mark it failed with path_error.
            job_id = _new_id("djob")
            job = {
                "id": job_id,
                "settings_id": active["id"],
                "subdirectory_id": None,
                "requested_subdirectory": subdir_in,
                "source_url": url_in,
                "source_url_normalized": source_url_norm,
                "fetch_url": fetch_url,
                "http_status": None,
                "content_type": None,
                "content_sha256": None,
                "bytes_written": None,
                "status": "failed",
                "error_code": "path_error",
                "error_message": "Requested subdirectory does not exist under active settings",
                "started_at": now,
                "finished_at": now,
                "created_at": now,
                "updated_at": now,
            }
            jobs.append(job)
            _save("download_jobs.json", jobs)
            return {
                "download_job": job,
                "markdown_file": None,
            }
        subdir_row = candidates[0]

    # --- create job queued ---
    job_id = _new_id("djob")
    job = {
        "id": job_id,
        "settings_id": active["id"],
        "subdirectory_id": subdir_row["id"] if subdir_row else None,
        "requested_subdirectory": subdir_in,
        "source_url": url_in,
        "source_url_normalized": source_url_norm,
        "fetch_url": fetch_url,
        "http_status": None,
        "content_type": None,
        "content_sha256": None,
        "bytes_written": None,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job)
    _save("download_jobs.json", jobs)

    def _persist_job_update():
        for i, r in enumerate(jobs):
            if r.get("id") == job_id:
                jobs[i] = job
                break
        _save("download_jobs.json", jobs)

    def _fail_job(code, msg):
        # transition to failed if allowed from current status
        allowed = {
            "queued": {"fetching", "failed"},
            "fetching": {"saving", "failed"},
            "saving": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        if "failed" not in allowed.get(job["status"], set()) and job["status"] != "failed":
            return _err("INVALID_TRANSITION", f"Cannot transition download job from {job['status']} to failed")
        job["status"] = "failed"
        job["error_code"] = code
        job["error_message"] = msg
        job["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        job["updated_at"] = job["finished_at"]
        _persist_job_update()
        return {
            "download_job": job,
            "markdown_file": None,
        }

    # --- fetching ---
    job["status"] = "fetching"
    job["started_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    job["updated_at"] = job["started_at"]
    _persist_job_update()

    try:
        req = urllib.request.Request(fetch_url, headers={"User-Agent": "MarkdownDownloader/1.0"})
        with urllib.request.urlopen(req, timeout=30) as resp:
            status = getattr(resp, "status", None)
            job["http_status"] = int(status) if status is not None else None
            job["content_type"] = resp.headers.get("Content-Type")
            body = resp.read()
    except urllib.error.HTTPError as e:
        # HTTPError has code and body
        job["http_status"] = int(getattr(e, "code", 0) or 0) or None
        return _fail_job("http_error", f"HTTP error while fetching: {getattr(e, 'code', '')}")
    except urllib.error.URLError as e:
        return _fail_job("network_error", f"Network error while fetching: {getattr(e, 'reason', '')}")
    except TimeoutError:
        return _fail_job("timeout", "Timed out while fetching")
    except Exception as e:
        # unexpected but must not raise
        return _fail_job("unknown", f"Unexpected error while fetching: {type(e).__name__}: {e}")

    # Validate http_status range if present
    if job["http_status"] is not None:
        if not (100 <= job["http_status"] <= 599):
            return _fail_job("http_error", "Invalid HTTP status returned")

    # --- saving ---
    if job["status"] != "fetching":
        return _err("INVALID_TRANSITION", "Download job not in fetching state for saving")
    job["status"] = "saving"
    job["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _persist_job_update()

    # compute safe relative path / filename
    def _slug(s):
        s = s.strip().lower()
        s = re.sub(r"[^a-z0-9\-._]+", "-", s)
        s = re.sub(r"-{2,}", "-", s).strip("-")
        return s or "download"

    p = urllib.parse.urlparse(source_url_norm)
    host = p.netloc.lower()
    path = p.path or "/"
    base = os.path.basename(path.rstrip("/")) or "index"
    base = _slug(base)
    # incorporate a short hash of normalized URL for uniqueness
    uhash = hashlib.sha256(source_url_norm.encode("utf-8")).hexdigest()[:12]
    file_name = f"{base}-{uhash}.md"

    rel_dir = subdir_row.get("relative_path") if subdir_row else ""
    if not isinstance(rel_dir, str):
        rel_dir = ""

    # prevent traversal: no '..' segments
    def _has_dotdot(segpath):
        parts = [p for p in segpath.replace("\\", "/").split("/") if p != ""]
        return any(part == ".." for part in parts)

    if _has_dotdot(rel_dir) or _has_dotdot(file_name):
        return _fail_job("path_error", "Directory traversal detected")

    relative_path = os.path.join(rel_dir, file_name) if rel_dir else file_name
    # relative_path must not be absolute
    if os.path.isabs(relative_path):
        return _fail_job("path_error", "relative_path must not be absolute")

    full_path = os.path.normpath(os.path.join(root_norm, relative_path))
    # full_path must start with root_norm
    root_prefix = root_norm + os.sep
    if not (full_path == root_norm or full_path.startswith(root_prefix)):
        return _fail_job("path_error", "Resolved path escapes root directory")

    if len(full_path) > max_path_length:
        return _fail_job("path_error", "Resolved path exceeds max_path_length")

    # ensure directory exists
    try:
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
    except OSError as e:
        return _fail_job("write_error", f"Unable to create directory: {e}")

    # write file
    try:
        with open(full_path, "wb") as f:
            f.write(body)
        bytes_written = len(body)
    except OSError as e:
        return _fail_job("write_error", f"Unable to write file: {e}")

    content_sha = hashlib.sha256(body).hexdigest()

    # succeed job
    if job["status"] != "saving":
        return _err("INVALID_TRANSITION", "Download job not in saving state for success")
    job["status"] = "succeeded"
    job["content_sha256"] = content_sha
    job["bytes_written"] = bytes_written
    job["error_code"] = None
    job["error_message"] = None
    job["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    job["updated_at"] = job["finished_at"]
    _persist_job_update()

    # create markdown_files row only after succeeded
    # uniqueness: unique(settings_id, relative_path) where present
    for r in files:
        if (
            isinstance(r, dict)
            and r.get("settings_id") == active["id"]
            and r.get("relative_path") == relative_path
            and r.get("status") == "present"
        ):
            # keep the file written, but index conflict -> mark job failed? would violate rule created only after succeeded.
            # treat as conflict at indexing stage; mark file index not created and return conflict error.
            # Also set job to failed is illegal transition from succeeded, so we must return CONFLICT without mutating job.
            return _err("CONFLICT", "A file with the same relative_path already exists in the index", relative_path=relative_path)

    file_id = _new_id("mfile")
    mf = {
        "id": file_id,
        "job_id": job_id,
        "settings_id": active["id"],
        "subdirectory_id": subdir_row["id"] if subdir_row else None,
        "relative_path": relative_path.replace("\\", "/"),
        "file_name": file_name,
        "full_path": full_path,
        "source_url": url_in,
        "content_sha256": content_sha,
        "size_bytes": bytes_written,
        "status": "present",
        "created_at": job["finished_at"],
        "updated_at": job["finished_at"],
    }

    # invariant: size_bytes equals bytes_written
    if mf["size_bytes"] != job["bytes_written"]:
        return _err("CONFLICT", "size_bytes must equal bytes_written")

    files.append(mf)
    _save("markdown_files.json", files)

    return {
        "download_job": job,
        "markdown_file": mf,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def list_downloaded_files(subdirectory=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0037000" if __import__("os").path.isdir("./environment_mix/0037000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, extra=None):
        # best-effort logging; never fail the call for logging issues
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
            row = {
                "id": f"req_{int(datetime.datetime.now(datetime.timezone.utc).timestamp()*1000)}_{len(logs)}",
                "endpoint": "list_downloaded_files",
                "credential_used": None,
                "status": status_code,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            }
            if isinstance(extra, dict):
                row.update(extra)
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _pick_active_settings(settings_rows):
        active_rows = []
        for s in settings_rows:
            if isinstance(s, dict) and s.get("active") is True and s.get("status") == "active" and isinstance(s.get("id"), str) and s.get("id"):
                active_rows.append(s)
        if not active_rows:
            return None
        # Prefer most recently updated/created
        def _key(r):
            return (r.get("updated_at") or r.get("created_at") or "")
        active_rows.sort(key=_key, reverse=True)
        return active_rows[0]

    def _validate_subdir_string(s):
        # Tool contract says VALIDATION_ERROR if not a valid name.
        # However the audit shows callers pass an ID too; accept both.
        if not isinstance(s, str):
            return "Field 'subdirectory' must be a string when provided."
        v = s.strip()
        if v == "":
            return None  # treat empty as not provided
        if "\x00" in v:
            return "Subdirectory must not contain NUL byte."
        # if it's clearly an id, allow as-is
        if v.startswith("mdsub_"):
            return None
        # name rules
        if v in (".", ".."):
            return "Subdirectory name must not be '.' or '..'."
        if len(v) < 1 or len(v) > 128:
            return "Subdirectory name length must be between 1 and 128."
        return None

    # ---- validate ----
    if subdirectory is not None:
        msg = _validate_subdir_string(subdirectory)
        if msg is not None:
            resp = _err("VALIDATION_ERROR", msg, subdirectory=subdirectory)
            _log(resp["error"]["code"])
            return resp
    sub = subdirectory.strip() if isinstance(subdirectory, str) else None
    if sub == "":
        sub = None

    # ---- resolve active settings ----
    settings = _load("download_settings.json")
    if not isinstance(settings, list):
        settings = []
    active = _pick_active_settings(settings)
    if active is None:
        resp = _err("NOT_FOUND", "No active download settings configured.")
        _log(resp["error"]["code"])
        return resp
    active_id = active.get("id")

    # ---- resolve subdirectory (optional) ----
    sub_id = None
    if sub is not None:
        subs = _load("subdirectories.json")
        if not isinstance(subs, list):
            subs = []
        if sub.startswith("mdsub_"):
            for r in subs:
                if isinstance(r, dict) and r.get("id") == sub and r.get("settings_id") == active_id and r.get("status") == "active":
                    sub_id = r.get("id")
                    break
        else:
            sub_norm = sub.strip().lower()
            for r in subs:
                if not isinstance(r, dict):
                    continue
                if r.get("settings_id") != active_id or r.get("status") != "active":
                    continue
                rn = r.get("name_normalized")
                if isinstance(rn, str) and rn == sub_norm:
                    sub_id = r.get("id")
                    break
                # fallback to name direct compare
                if isinstance(r.get("name"), str) and r.get("name").strip() == sub:
                    sub_id = r.get("id")
                    break
        if sub_id is None:
            resp = _err("NOT_FOUND", "Subdirectory not found.", subdirectory=sub)
            _log(resp["error"]["code"])
            return resp

    # ---- list files ----
    files = _load("markdown_files.json")
    if not isinstance(files, list):
        files = []
    out = []
    for f in files:
        if not isinstance(f, dict):
            continue
        if f.get("status") != "present":
            continue
        if f.get("settings_id") != active_id:
            continue
        if sub_id is not None and f.get("subdirectory_id") != sub_id:
            continue
        out.append(f)

    # stable sort: newest first (created_at desc), then id
    def _skey(r):
        return (r.get("created_at") or "", r.get("id") or "")
    out.sort(key=_skey, reverse=True)

    resp = {
        "files": out,
        "total": len(out),
        "settings_id": active_id,
    }
    _log("OK", {"result_count": len(out)})
    return resp

def set_download_directory(directory, **_extra):
    import json, os, datetime, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0037000" if __import__("os").path.isdir("./environment_mix/0037000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
            logs.append({
                "id": f"req_{int(datetime.datetime.now(datetime.timezone.utc).timestamp()*1000)}_{len(logs)}",
                "endpoint": "set_download_directory",
                "credential_used": None,
                "status": status_code,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    # ---- validate ----
    if not isinstance(directory, str) or not directory.strip():
        resp = _err("VALIDATION_ERROR", "Field 'directory' must be a non-empty string.")
        _log(resp["error"]["code"])
        return resp
    directory_in = directory.strip()

    # root_directory must be absolute path; normalize into root_directory_normalized
    try:
        root_norm = os.path.abspath(os.path.normpath(directory_in))
        if len(root_norm) > 1 and root_norm.endswith(os.sep):
            root_norm = root_norm.rstrip(os.sep)
    except Exception:
        resp = _err("VALIDATION_ERROR", "Field 'directory' must be a valid path string.", directory=directory)
        _log(resp["error"]["code"])
        return resp

    if not os.path.isabs(root_norm):
        resp = _err("VALIDATION_ERROR", "root_directory must be an absolute path.", directory=directory_in)
        _log(resp["error"]["code"])
        return resp

    # max_path_length constraints apply to settings record, not directory itself, but enforce valid range for record.
    max_path_length = 4096  # reasonable default within [64, 32767]
    if not (64 <= max_path_length <= 32767):
        max_path_length = 4096

    # ensure directory can be used
    try:
        os.makedirs(root_norm, exist_ok=True)
    except OSError as e:
        resp = _err("CONFLICT", "Directory cannot be created/used.", detail=str(e))
        _log(resp["error"]["code"])
        return resp

    settings = _load("download_settings.json")
    if not isinstance(settings, list):
        settings = []

    # Find currently active
    active = None
    for s in settings:
        if isinstance(s, dict) and s.get("active") is True and s.get("status") == "active":
