        resp = {"download_settings": active}
        _log("OK")
        return resp

    # enforce "only one active settings record at a time" & "root_directory_normalized derived and unique among active"
    # We'll supersede any existing active record, then create a new active record.
    now = _now_iso()
    changed = False
    if active is not None:
        # transition active -> superseded (allowed)
        for i, s in enumerate(settings):
            if isinstance(s, dict) and s.get("id") == active.get("id"):
                settings[i] = dict(s)
                settings[i]["active"] = False
                settings[i]["status"] = "superseded"
                settings[i]["updated_at"] = now
                changed = True
                break

    # Build new settings record; carry forward allow_relative_subdirectories & max_path_length if possible
    allow_rel = True
    if active is not None and isinstance(active.get("allow_relative_subdirectories"), bool):
        allow_rel = active.get("allow_relative_subdirectories")

    if active is not None and isinstance(active.get("max_path_length"), int) and 64 <= active.get("max_path_length") <= 32767:
        max_path_length = active.get("max_path_length")

    # Ensure there is no other active record left (defensive) and normalized uniqueness among active (defensive)
    for s in settings:
        if not isinstance(s, dict):
            continue
        if s.get("active") is True and s.get("status") == "active":
            resp = _err("CONFLICT", "Invariant violation: multiple active settings records exist; cannot set directory safely.")
            _log(resp["error"]["code"])
            return resp
        if s.get("active") is True and s.get("status") == "active" and s.get("root_directory_normalized") == root_norm:
            resp = _err("CONFLICT", "An active settings record already uses this directory.", directory=root_norm)
            _log(resp["error"]["code"])
            return resp

    new_id = f"mdset_{uuid.uuid4().hex[:26]}"
    new_row = {
        "id": new_id,
        "active": True,
        "root_directory": directory_in,
        "root_directory_normalized": root_norm,
        "allow_relative_subdirectories": allow_rel,
        "max_path_length": int(max_path_length),
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }
    settings.append(new_row)
    changed = True

    if not changed:
        resp = _err("NOT_FOUND", "No changes were applied.")
        _log(resp["error"]["code"])
        return resp

    try:
        _save("download_settings.json", settings)
    except Exception as e:
        resp = _err("CONFLICT", "Failed to persist settings update.", detail=str(e))
        _log(resp["error"]["code"])
        return resp

    resp = {"download_settings": new_row}
    _log("OK")
    return resp

