def create_subdirectory(name, **_extra):
    import json, os, datetime, platform, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0037000" if __import__("os").path.isdir("./environment_mix/0037000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _norm_root(p):
        # Keep absolute, normalize separators, remove trailing slashes (except root)
        p2 = os.path.abspath(os.path.expanduser(p))
        p2 = os.path.normpath(p2)
        if p2 != os.path.sep:
            p2 = p2.rstrip("/\\")
        return p2

    def _default_root():
        home = os.path.expanduser("~")
        if os.path.isabs(home):
            return _norm_root(os.path.join(home, "markdown_downloads"))
        # fallback
        return _norm_root(os.path.join(os.getcwd(), "markdown_downloads"))

    def _name_normalized(nm):
        nm2 = nm.strip()
        if os.name == "nt":
            return nm2.lower()
        return nm2

    def _valid_single_segment(nm):
        # no separators; allow_relative_subdirectories=false -> must be single segment
        return ("/" not in nm) and ("\\" not in nm)

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    started = datetime.datetime.now(datetime.timezone.utc)
    status_code = "OK"

    # Validate input
    if not isinstance(name, str):
        return _err("VALIDATION_ERROR", "Field 'name' must be a string.")
    raw_name = name
    nm = raw_name.strip()
    if len(nm) < 1 or len(nm) > 128:
        return _err("VALIDATION_ERROR", "Subdirectory name length must be between 1 and 128.")
    if nm in (".", ".."):
        return _err("VALIDATION_ERROR", "Subdirectory name must not be '.' or '..'.")
    if "\x00" in nm:
        return _err("VALIDATION_ERROR", "Subdirectory name must not contain NUL byte.")

    # Load settings; ensure one active exists, else create default (per rules)
    settings = _load("download_settings.json")
    active_settings = None
    for s in settings:
        if isinstance(s, dict) and s.get("active") is True and s.get("status") == "active":
            active_settings = s
            break

    if active_settings is None:
        # Create default active settings
        root = _default_root()
        created = _now()
        new_settings = {
            "id": _gen_id("dset"),
            "active": True,
            "root_directory": root,
            "root_directory_normalized": _norm_root(root),
            "allow_relative_subdirectories": False,
            "max_path_length": 4096,
            "status": "active",
            "created_at": created,
            "updated_at": created,
        }
        # Ensure uniqueness of active=true: supersede any other active if present (repair)
        for s in settings:
            if isinstance(s, dict) and s.get("active") is True and s.get("status") == "active":
                s["active"] = False
                if s.get("status") == "active":
                    s["status"] = "superseded"
                s["updated_at"] = created
        settings.append(new_settings)
        _save("download_settings.json", settings)
        active_settings = new_settings

    allow_rel = bool(active_settings.get("allow_relative_subdirectories"))
    if not allow_rel and not _valid_single_segment(nm):
        return _err("VALIDATION_ERROR", "Subdirectory name must be a single path segment (no '/' or '\\').")

    name_norm = _name_normalized(nm)

    # Check duplicates under active settings among active subdirectories
    subs = _load("subdirectories.json")
    for sd in subs:
        if not isinstance(sd, dict):
            continue
        if sd.get("settings_id") == active_settings["id"] and sd.get("status") == "active":
            if sd.get("name_normalized") == name_norm:
                return _err("CONFLICT", "An active subdirectory with the same name already exists.", existing_id=sd.get("id"))

    # Compute paths and validate traversal
    rel_path = nm if allow_rel else nm  # still nm; allow_rel true can include separators but must not traverse
    # traversal prevention: no '..' segments, not absolute
    if os.path.isabs(rel_path):
        return _err("VALIDATION_ERROR", "Subdirectory relative path must not be absolute.")
    parts = [p for p in rel_path.replace("\\", "/").split("/") if p != ""]
    if any(p == ".." for p in parts):
        return _err("VALIDATION_ERROR", "Subdirectory name/path must not contain '..' segments.")
    if any("\x00" in p for p in parts):
        return _err("VALIDATION_ERROR", "Subdirectory name/path must not contain NUL byte.")

    root_norm = active_settings.get("root_directory_normalized")
    if not isinstance(root_norm, str) or not root_norm:
        return _err("VALIDATION_ERROR", "Active settings is missing root_directory_normalized.")
    full_path = os.path.normpath(os.path.join(root_norm, rel_path))
    # Ensure full_path stays within root
    try:
        common = os.path.commonpath([root_norm, full_path])
    except ValueError:
        return _err("VALIDATION_ERROR", "Computed path is invalid.")
    if os.path.normcase(common) != os.path.normcase(root_norm):
        return _err("VALIDATION_ERROR", "Directory traversal detected: subdirectory escapes root directory.")

    max_len = active_settings.get("max_path_length")
    if not isinstance(max_len, int) or max_len < 64 or max_len > 32767:
        return _err("VALIDATION_ERROR", "Active settings has invalid max_path_length.")
    if len(full_path) > max_len:
        return _err("VALIDATION_ERROR", "Full path exceeds max_path_length for active settings.", max_path_length=max_len)

    # Ensure directory exists on disk; if a non-directory exists at that path -> conflict
    try:
        if os.path.exists(full_path) and not os.path.isdir(full_path):
            return _err("CONFLICT", "A non-directory path exists with the same name.", full_path=full_path)
        os.makedirs(full_path, exist_ok=True)
        if not os.path.isdir(full_path):
            return _err("CONFLICT", "Path could not be created as a directory.", full_path=full_path)
    except PermissionError:
        return _err("UNAUTHORIZED", "Permission denied creating subdirectory on disk.", full_path=full_path)
    except OSError as e:
        return _err("CONFLICT", "Failed to create subdirectory on disk.", full_path=full_path, os_error=str(e))

    now = _now()
    row = {
        "id": _gen_id("subd"),
        "settings_id": active_settings["id"],
        "name": nm,
        "name_normalized": name_norm,
        "relative_path": rel_path.replace("\\", "/") if allow_rel else rel_path,
        "full_path": full_path,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }
    subs.append(row)
    _save("subdirectories.json", subs)

    # Minimal observable dynamics: record usage if collection exists (best-effort, no failure if absent)
    try:
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            latency_ms = int((datetime.datetime.now(datetime.timezone.utc) - started).total_seconds() * 1000)
            logs.append({
                "id": _gen_id("req"),
                "endpoint": "create_subdirectory",
                "timestamp": _now(),
                "status": status_code,
                "latency_ms": latency_ms,
            })
            _save("request_logs.json", logs)
    except Exception:
        pass

    return {"subdirectory": row}

