                "timestamp": _now_iso(),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    # ---- validate ----
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived"):
            resp = _err("VALIDATION_ERROR", "Invalid 'status' filter; must be 'active' or 'archived'.", status=status)
            _log(resp["error"]["code"])
            return resp

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or not (1 <= page_size <= 200):
        resp = _err("VALIDATION_ERROR", "Field 'page_size' must be an integer between 1 and 200.", page_size=page_size)
        _log(resp["error"]["code"])
        return resp

    # page_token is treated as an opaque cursor; accept any string. If invalid/unrecognized, start from beginning.
    if page_token is not None and not isinstance(page_token, str):
        resp = _err("VALIDATION_ERROR", "Field 'page_token' must be a string.", page_token=page_token)
        _log(resp["error"]["code"])
        return resp

    settings = _load("download_settings.json")
    if not isinstance(settings, list):
        settings = []
    active = None
    for s in settings:
        if isinstance(s, dict) and s.get("active") is True and s.get("status") == "active":
            if active is None:
                active = s
            else:
                akey = (active.get("updated_at") or active.get("created_at") or "")
                skey = (s.get("updated_at") or s.get("created_at") or "")
                if skey > akey:
                    active = s
    if active is None:
        resp = _err("NOT_FOUND", "No active download settings configured.")
        _log(resp["error"]["code"])
        return resp

    subs = _load("subdirectories.json")
    if not isinstance(subs, list):
        subs = []

    rows = []
    for sd in subs:
        if not isinstance(sd, dict):
            continue
        if sd.get("settings_id") != active.get("id"):
            continue
        if status is not None and sd.get("status") != status:
            continue
        rows.append(sd)

    rows.sort(key=lambda r: ((r.get("created_at") or ""), (r.get("id") or "")))
    start = 0
    if page_token:
        # token is last seen id; find next index after that id; if not found, start at 0 (do not error)
        for i, r in enumerate(rows):
            if r.get("id") == page_token:
                start = i + 1
                break

    page = rows[start:start + page_size]
    next_cursor = None
    has_more = start + page_size < len(rows)
    if has_more and page:
        next_cursor = page[-1].get("id")

    resp = {
        "subdirectories": page,
        "total": len(rows),
        "has_more": has_more,
        "next_cursor": next_cursor,
    }
    _log("OK")
    return resp

