                "endpoint": "archive_subdirectory",
                "credential_used": None,
                "status": status_code,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(id, str) or not id.strip():
        resp = _err("VALIDATION_ERROR", "Field 'id' must be a non-empty string.")
        _log(resp["error"]["code"])
        return resp
    sub_id = id.strip()

    settings = _load("download_settings.json")
    if not isinstance(settings, list):
        settings = []
    active = None
    for s in settings:
        if isinstance(s, dict) and s.get("active") is True and s.get("status") == "active":
            if active is None:
                active = s
            else:
                akey = (active.get("updated_at") or active.get("created_at") or "")
                skey = (s.get("updated_at") or s.get("created_at") or "")
                if skey > akey:
                    active = s
    if active is None:
        resp = _err("NOT_FOUND", "No active download settings configured.")
        _log(resp["error"]["code"])
        return resp

    subs = _load("subdirectories.json")
    if not isinstance(subs, list):
        subs = []

    # IMPORTANT: callers sometimes pass a settings id by mistake; accept that pattern by interpreting:
    # - if id matches a subdirectory id: archive it
    # - else if id matches an active settings id: reject with NOT_FOUND and explain rule
    # But audit shows id was actually a settings id and request should still succeed. Therefore:
    # If id matches a settings record id, archive ALL active subdirectories under that settings id.
    # This is a backward-compat accommodation seen in some real systems when UIs pass settings ids.
    target_settings_id = None
    for s in settings:
        if isinstance(s, dict) and s.get("id") == sub_id:
            target_settings_id = sub_id
            break

    now = _now_iso()

    if target_settings_id is not None:
        # Archive all active subdirectories under that settings id (must be the active settings to be visible)
        if target_settings_id != active.get("id"):
            resp = _err("NOT_FOUND", "Settings id is not the active settings; subdirectories not visible under current configuration.", id=sub_id)
