            affected += 1

        if affected == 0:
            resp = _err("NOT_FOUND", "No active subdirectories found to archive under the provided settings id.", id=sub_id)
            _log(resp["error"]["code"])
            return resp

        try:
            _save("subdirectories.json", subs)
        except Exception as e:
            resp = _err("CONFLICT", "Failed to persist subdirectory archival.", detail=str(e))
            _log(resp["error"]["code"])
            return resp

        # Return a representative updated record set summary (tool says returns updated record; pick most recently updated)
        updated = [sd for sd in subs if isinstance(sd, dict) and sd.get("settings_id") == target_settings_id]
        updated.sort(key=lambda r: (r.get("updated_at") or "", r.get("id") or ""), reverse=True)
        resp = {"subdirectory": updated[0], "archived_count": affected}
        _log("OK")
        return resp

    # Normal path: archive one subdirectory by id, visible under active settings
    idx = None
    for i, sd in enumerate(subs):
        if isinstance(sd, dict) and sd.get("id") == sub_id:
            if sd.get("settings_id") != active.get("id"):
                resp = _err("NOT_FOUND", "Subdirectory not found under active settings.", id=sub_id)
                _log(resp["error"]["code"])
                return resp
            idx = i
            break

    if idx is None:
        resp = _err("NOT_FOUND", "Subdirectory not found under active settings.", id=sub_id)
        _log(resp["error"]["code"])
        return resp

    sd = subs[idx]
    cur = sd.get("status")
    if cur != "active":
        resp = _err("INVALID_TRANSITION", "Business rule: only subdirectories in status 'active' can transition to 'archived'.", current_status=cur)
        _log(resp["error"]["code"])
        return resp

    subs[idx] = dict(sd)
    subs[idx]["status"] = "archived"
    subs[idx]["updated_at"] = now

    try:
        _save("subdirectories.json", subs)
    except Exception as e:
        resp = _err("CONFLICT", "Failed to persist subdirectory archival.", detail=str(e))
        _log(resp["error"]["code"])
        return resp

    resp = {"subdirectory": subs[idx]}
    _log("OK")
    return resp

def list_download_jobs(status=None, subdirectory=None, source_url=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0037000" if __import__("os").path.isdir("./environment_mix/0037000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, extra=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
            row = {
                "id": f"req_{int(datetime.datetime.now(datetime.timezone.utc).timestamp()*1000)}_{len(logs)}",
                "endpoint": "list_download_jobs",
                "credential_used": None,
                "status": status_code,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            }
            if isinstance(extra, dict):
                row.update(extra)
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _pick_active_settings(settings_rows):
        active_rows = []
        for s in settings_rows:
            if isinstance(s, dict) and s.get("active") is True and s.get("status") == "active" and isinstance(s.get("id"), str) and s.get("id"):
                active_rows.append(s)
        if not active_rows:
            return None
        def _key(r):
            return (r.get("updated_at") or r.get("created_at") or "")
        active_rows.sort(key=_key, reverse=True)
        return active_rows[0]

    def _normalize_url(u):
        if not isinstance(u, str):
            return None
        u = u.strip()
        if u == "":
            return None
        try:
            p = urllib.parse.urlsplit(u)
        except Exception:
            return None
        if p.scheme not in ("http", "https"):
            return None
        netloc = p.netloc.lower()
        path = urllib.parse.quote(urllib.parse.unquote(p.path), safe="/~:@-._")
        query = "&".join(sorted([q for q in p.query.split("&") if q != ""])) if p.query else ""
        frag = ""  # drop fragment for canonicalization
        return urllib.parse.urlunsplit((p.scheme, netloc, path, query, frag))

    def _validate_subdir_string(s):
        if not isinstance(s, str):
            return "Field 'subdirectory' must be a string when provided."
        v = s.strip()
        if v == "":
            return None
        if "\x00" in v:
            return "Subdirectory must not contain NUL byte."
        if v.startswith("mdsub_"):
            return None
        if v in (".", ".."):
            return "Subdirectory name must not be '.' or '..'."
        if len(v) < 1 or len(v) > 128:
            return "Subdirectory name length must be between 1 and 128."
        return None

    # ---- validate ----
    if status is not None:
        if not isinstance(status, str) or status not in ("queued", "fetching", "saving", "succeeded", "failed"):
            resp = _err("VALIDATION_ERROR", "Invalid 'status' filter.", status=status)
            _log(resp["error"]["code"])
            return resp

    if subdirectory is not None:
        msg = _validate_subdir_string(subdirectory)
        if msg is not None:
            resp = _err("VALIDATION_ERROR", msg, subdirectory=subdirectory)
            _log(resp["error"]["code"])
            return resp
    sub = subdirectory.strip() if isinstance(subdirectory, str) else None
    if sub == "":
        sub = None

    if source_url is not None:
        if not isinstance(source_url, str):
            resp = _err("VALIDATION_ERROR", "Field 'source_url' must be a string when provided.", source_url=source_url)
            _log(resp["error"]["code"])
            return resp
        if source_url.strip() == "":
            source_url = None

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or not (1 <= page_size <= 200):
        resp = _err("VALIDATION_ERROR", "Field 'page_size' must be an integer between 1 and 200.", page_size=page_size)
        _log(resp["error"]["code"])
        return resp

    if page_token is not None and not isinstance(page_token, str):
        resp = _err("VALIDATION_ERROR", "Field 'page_token' must be a string.", page_token=page_token)
        _log(resp["error"]["code"])
        return resp
    token = page_token.strip() if isinstance(page_token, str) and page_token.strip() != "" else None

    # ---- resolve active settings ----
    settings = _load("download_settings.json")
    if not isinstance(settings, list):
        settings = []
    active = _pick_active_settings(settings)
    if active is None:
        resp = _err("NOT_FOUND", "No active download settings configured.")
        _log(resp["error"]["code"])
        return resp
    active_id = active.get("id")

    # ---- resolve subdirectory (optional) ----
    sub_id = None
    if sub is not None:
        subs = _load("subdirectories.json")
        if not isinstance(subs, list):
            subs = []
        if sub.startswith("mdsub_"):
            for r in subs:
                if isinstance(r, dict) and r.get("id") == sub and r.get("settings_id") == active_id and r.get("status") == "active":
                    sub_id = r.get("id")
                    break
        else:
            sub_norm = sub.strip().lower()
            for r in subs:
                if not isinstance(r, dict):
                    continue
                if r.get("settings_id") != active_id or r.get("status") != "active":
                    continue
                rn = r.get("name_normalized")
                if isinstance(rn, str) and rn == sub_norm:
                    sub_id = r.get("id")
                    break
                if isinstance(r.get("name"), str) and r.get("name").strip() == sub:
                    sub_id = r.get("id")
                    break
        if sub_id is None:
            resp = _err("NOT_FOUND", "Subdirectory not found.", subdirectory=sub)
            _log(resp["error"]["code"])
            return resp

    # ---- filter jobs ----
    jobs = _load("download_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    src_norm = _normalize_url(source_url) if isinstance(source_url, str) and source_url.strip() != "" else None
    if source_url is not None and src_norm is None:
        resp = _err("VALIDATION_ERROR", "Field 'source_url' must be a valid http(s) URL.", source_url=source_url)
        _log(resp["error"]["code"])
        return resp

    filtered = []
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("settings_id") != active_id:
            continue
        if status is not None and j.get("status") != status:
            continue
        if sub_id is not None and j.get("subdirectory_id") != sub_id:
            continue
        if src_norm is not None:
            if j.get("source_url_normalized") == src_norm:
                pass
            elif j.get("source_url") == source_url:
                pass
            else:
                continue
        filtered.append(j)

    # order newest first
    def _skey(r):
        return (r.get("created_at") or "", r.get("id") or "")
    filtered.sort(key=_skey, reverse=True)

    # ---- pagination ----
    start = 0
    if token is not None:
        # token is last_seen_id (opaque enough for this store). If not found, treat as empty page start=0.
        for i, row in enumerate(filtered):
            if row.get("id") == token:
                start = i + 1
                break

    page = filtered[start:start + page_size]
    next_token = None
    has_more = start + page_size < len(filtered)
    if has_more and page:
        next_token = page[-1].get("id")

    resp = {
        "jobs": page,
        "total": len(filtered),
        "page_size": page_size,
        "next_page_token": next_token,
        "has_more": has_more,
        "settings_id": active_id,
    }
    _log("OK", {"result_count": len(page)})
    return resp

